      console.log('Could not parse audit data:', body);
    }

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'success', message: 'Audit logged' }));
  });
});

server.listen(3003, () => {
  console.log('Audit server listening on port 3003');
});

