const fs = require('fs');
const path = require('path');

// Path to migrations directory and env file
const migrationsDir = './migrations';
const envFilePath = './.env.test';

// Function to parse .env file
function parseEnvFile(filePath) {
  const envVars = {};
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    for (const line of lines) {
      // Skip empty lines and comments
      if (line.trim() === '' || line.startsWith('#')) {
        continue;
      }

      const [key, ...values] = line.split('=');
      const value = values.join('=').trim();

      // Remove quotes if present
      envVars[key.trim()] = value.replace(/^"(.*)"$/, '$1').replace(/^'(.*)'$/, '$1');
    }
  } catch (error) {
    console.warn(`Warning: Could not read ${filePath}: ${error.message}`);
  }

  return envVars;
}

// Function to run migrations
async function runMigrations() {
  try {
    // Load environment variables
    const envVars = parseEnvFile(envFilePath);
    const databaseUrl = envVars.DATABASE_URL;

    if (databaseUrl) {
      console.log(`Connected to database: ${databaseUrl}`);
    } else {
      console.log('No DATABASE_URL found in .env.test');
    }

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.log('Migrations directory does not exist. Creating it...');
      fs.mkdirSync(migrationsDir, { recursive: true });
      console.log('Migrations directory created.');
      return;
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter only .sql files and sort them
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log('\nMigration files to apply (in order):');

    // Log each filename in order
    for (const file of sqlFiles) {
      console.log('- ' + file);
      // In a real implementation, you would execute the SQL here
      // await executeSQLFile(path.join(migrationsDir, file));
    }

    console.log(`\nTotal migrations found: ${sqlFiles.length}`);

  } catch (error) {
    console.error('Error reading migration files:', error.message);
    process.exit(1);
  }
}

// Execute migrations
runMigrations();

