const fs = require('fs');
const path = require('path');
const http = require('http');

// Function to parse .env file
function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.log(`Environment file '${filePath}' not found.`);
    return {};
  }

  const envConfig = {};
  const data = fs.readFileSync(filePath, 'utf8');

  data.split('\n').forEach(line => {
    // Skip empty lines and comments
    if (line.trim() === '' || line.startsWith('#')) {
      return;
    }

    const [key, ...values] = line.split('=');
    envConfig[key.trim()] = values.join('=').trim();
  });

  return envConfig;
}

// Function to send audit data
function sendAuditData(envVars) {
  const postData = JSON.stringify(envVars);

  const options = {
    hostname: 'localhost',
    port: 3003,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = http.request(options, (res) => {
    console.log(`Audit service response status: ${res.statusCode}`);

    res.on('data', (chunk) => {
      // Consume response data
    });

    res.on('end', () => {
      // Continue with migration after audit
      runMigrations();
    });
  });

  req.on('error', (e) => {
    console.log('Audit service error:', e.message);
    // Continue with migration even if audit fails
    runMigrations();
  });

  req.write(postData);
  req.end();
}

// Function to run migrations
function runMigrations() {
  // Directory containing migration files
  const migrationsDir = './migrations';

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.log(`Migrations directory '${migrationsDir}' does not exist.`);
    process.exit(1);
  }

  // Read all files from migrations directory
  fs.readdir(migrationsDir, (err, files) => {
    if (err) {
      console.error('Error reading migrations directory:', err);
      process.exit(1);
    }

    // Filter only .sql files and sort them
    const sqlFiles = files
      .filter(file => path.extname(file) === '.sql')
      .sort();

    // Log each migration file that would be applied
    console.log('Migration files to be applied in order:');
    sqlFiles.forEach(file => {
      console.log('- ', file);
    });

    // In a real implementation, you would:
    // 1. Connect to your database
    // 2. Check which migrations have already been applied
    // 3. Apply only the new ones
    // 4. Record the applied migrations

    console.log(`\nTotal migrations found: ${sqlFiles.length}`);
  });
}

// Load environment variables from .env.test
const envVars = loadEnvFile('.env.test');
const databaseUrl = envVars.DATABASE_URL;

// Log database connection
if (databaseUrl) {
  console.log(`Connected to database: ${databaseUrl}`);
} else {
  console.log('No DATABASE_URL found in .env.test');
}

// Send audit data before running migrations
console.log('Sending audit data to compliance service...');
sendAuditData(envVars);
